/**
 * 치수 변수 풀기: DIMSTYLE 표 값 + ACAD DSTYLE 재지정(확장 데이터).
 * 핸들 값(340~347)은 이름으로 바꾸고, 크기 변수는 DIMSCALE을 곱해 둔다.
 */
import { DIM_HANDLE_CODES, DIM_VAR_CODES, DIM_VAR_DEFAULTS } from '../../core/dimvars';
import { type CadDocument, type DimStyle, type DimensionEntity, MODEL_SPACE, type TextStyle, tableKey } from '../../core/model';

export type RawVars = Record<string, number | string>;

/** 핸들 → 이름 */
function byHandle(doc: CadDocument, code: number, h: string): string | null {
  const key = h.trim().toUpperCase().replace(/^0+(?=.)/, '');
  if (!/^[0-9A-F]+$/.test(key)) return null;
  if (code === 340) {
    for (const s of doc.textStyles.values()) if (s.handle === key) return s.name;
  } else if (code >= 345) {
    for (const l of doc.linetypes.values()) if (l.handle === key) return l.name;
  } else {
    for (const r of doc.blockRecords.values()) if (r.handle === key) return r.name;
    for (const b of doc.blocks.values()) if (b.recordHandle === key || b.handle === key) return b.name;
  }
  return null;
}

const num = (v: number | string | undefined, d: number): number => {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  return Number.isFinite(n) ? n : d;
};

/** 옛 DIMUNIT(270) → DIMLUNIT·DIMFRAC */
const OLD_UNIT: Record<number, [number, number]> = { 1: [1, 0], 2: [2, 0], 3: [3, 0], 4: [4, 0], 5: [5, 0], 6: [4, 2], 7: [5, 2], 8: [6, 0] };

/**
 * R2007 이전 파일: AutoCAD는 새 치수 변수를 확장 데이터(ACAD_DSTYLE_…)로 남긴다.
 * 선종류(380·381·382 → 핸들)와 문자 채움(376)만 읽는다.
 */
const XDATA_VARS: Record<string, [number, string]> = {
  ACAD_DSTYLE_DIM_LINETYPE: [380, 'DIMLTYPE'],
  ACAD_DSTYLE_DIM_EXT1_LINETYPE: [381, 'DIMLTEX1'],
  ACAD_DSTYLE_DIM_EXT2_LINETYPE: [382, 'DIMLTEX2'],
};

function xdataVars(doc: CadDocument, xdata: { app: string; items: { code: number; value: unknown }[] }[] | undefined, out: RawVars, only: Set<string> | null): void {
  if (!xdata) return;
  for (const x of xdata) {
    const app = x.app.toUpperCase();
    const lt = XDATA_VARS[app];
    if (lt && (!only || only.has(lt[1]))) {
      const h = x.items.find((i) => i.code === 1005);
      if (typeof h?.value === 'string') {
        const name = byHandle(doc, 345, h.value);
        if (name) out[lt[1]] = name;
      }
    } else if (app === 'ACAD_DSTYLE_DIMTEXT_FILL' && (!only || only.has('DIMTFILL'))) {
      const i = x.items.findIndex((it) => it.code === 1070 && it.value === 376);
      const v = x.items[i + 1]?.value;
      if (i >= 0 && typeof v === 'number') out.DIMTFILL = v;
    }
  }
}

/**
 * 하위 치수 스타일(AutoCAD "사용 대상"): 부모 이름 뒤 $0 선형·정렬, $2 각도, $3 지름, $4 반지름(꺾기 포함), $6 세로좌표, $7 지시선.
 * 치수는 부모 스타일을 가리키고, 그 종류의 하위 스타일이 있으면 그 값으로 그린다. 호 길이 치수는 하위 스타일이 없다
 */
export function childStyleSuffix(d: { dimType?: number; subtype?: string }): string | null {
  if (d.subtype === 'LEADER') return '7';
  if (d.dimType === undefined) return null;
  if (d.subtype === 'ARC_DIMENSION') return null;
  if (d.subtype === 'LARGE_RADIAL_DIMENSION') return '4';
  const t = d.dimType & 7;
  return t === 0 || t === 1 ? '0' : t === 2 || t === 5 ? '2' : t === 3 ? '3' : t === 4 ? '4' : t === 6 ? '6' : null;
}

/** 치수 종류에 맞는 하위 스타일(없으면 null) */
export function childStyleOf(doc: CadDocument, d: { dimStyle: string; dimType?: number; subtype?: string }): DimStyle | null {
  const suf = childStyleSuffix(d);
  if (suf === null) return null;
  return doc.dimStyles.get(tableKey(`${d.dimStyle || 'Standard'}$${suf}`)) ?? null;
}

/**
 * 한 편집 안에서 치수 스타일에서 오는 값(기본값 + 스타일 + 옛 변수 + 스타일 확장 자료)을 스타일마다 한 번만 푼다.
 * 77차 — 치수 1만 개를 옮기면 치수마다 기본값 74개를 펼치고 스타일 값을 덮어써 다시 만들기 시간의 약 4분의 3이었다.
 * 스타일 값은 선종류 표(핸들 → 이름)에도 기대므로 문서가 바뀌지 않는 구간(편집 작업을 모으는 동안)에만 쓴다
 */
let styleCache: Map<string, RawVars> | null = null;

/** fn을 도는 동안 치수 스타일 값을 한 번만 푼다(그동안 문서의 치수 스타일·선종류·머리말을 바꾸지 않아야 한다) */
export function withDimVarsCache<T>(fn: () => T): T {
  if (styleCache) return fn();
  styleCache = new Map();
  try {
    return fn();
  } finally {
    styleCache = null;
  }
}

/** 기본값 + 스타일(없으면 머리말 $DIM) + 옛 변수 + 스타일 확장 자료 */
function styleVars(doc: CadDocument, ds: DimStyle | undefined): RawVars {
  const out: RawVars = { ...DIM_VAR_DEFAULTS };
  if (ds) {
    Object.assign(out, ds.vars);
    // R14 이전 스타일: DIMUNIT·DIMFIT만 있다
    if (ds.vars.DIMLUNIT === undefined && ds.vars.DIMUNIT !== undefined) {
      const m = OLD_UNIT[num(ds.vars.DIMUNIT, 2)];
      if (m) {
        out.DIMLUNIT = m[0];
        if (ds.vars.DIMFRAC === undefined) out.DIMFRAC = m[1];
      }
    }
    if (ds.vars.DIMATFIT === undefined && ds.vars.DIMFIT !== undefined) {
      const f = num(ds.vars.DIMFIT, 3);
      out.DIMATFIT = f <= 3 ? f : 3;
      if (ds.vars.DIMTMOVE === undefined) out.DIMTMOVE = f === 4 ? 1 : f === 5 ? 2 : 0;
    }
    const missing = new Set(['DIMLTYPE', 'DIMLTEX1', 'DIMLTEX2', 'DIMTFILL'].filter((k) => ds.vars[k] === undefined));
    if (missing.size) xdataVars(doc, ds.xdata, out, missing);
  } else for (const [k, v] of doc.header) if (k.startsWith('$DIM') && (typeof v === 'number' || typeof v === 'string')) out[k.slice(1)] = v;
  return out;
}

/** 치수의 변수 값(스타일 + 재지정). 스타일이 없으면 머리말 $DIM 값을 쓴다. */
export function rawDimVars(doc: CadDocument, d: Pick<DimensionEntity, 'dimStyle' | 'overrides'> & { xdata?: DimensionEntity['xdata']; dimType?: number; subtype?: string }): RawVars {
  let out: RawVars;
  // 스타일 이름과 하위 스타일 접미사가 같으면 같은 스타일이다
  const key = styleCache ? `${d.dimStyle}\u0000${childStyleSuffix(d) ?? ''}` : '';
  const hit = styleCache?.get(key);
  if (hit) out = { ...hit };
  else {
    const base = styleVars(doc, childStyleOf(doc, d) ?? doc.dimStyles.get(tableKey(d.dimStyle || 'Standard')));
    styleCache?.set(key, base);
    out = styleCache ? { ...base } : base;
  }
  xdataVars(doc, d.xdata, out, null);
  if (d.overrides) {
    const ov = d.overrides;
    for (const [codeS, v] of Object.entries(ov)) {
      const code = Number(codeS);
      const name = DIM_VAR_CODES[code];
      if (!name) continue;
      if (DIM_HANDLE_CODES.has(code) && typeof v === 'string') out[name] = byHandle(doc, code, v) ?? v;
      else if (DIM_HANDLE_CODES.has(code) && typeof v === 'number') out[name] = byHandle(doc, code, v.toString(16)) ?? '';
      else out[name] = v;
    }
    if (ov[270] !== undefined && ov[277] === undefined) {
      const m = OLD_UNIT[Number(ov[270])];
      if (m) {
        out.DIMLUNIT = m[0];
        if (ov[276] === undefined) out.DIMFRAC = m[1];
      }
    }
  }
  return out;
}

/** 치수가 놓인 공간을 아는 데 쓰는 값(도면 공간 표지 67, 소유 블록 레코드) */
export interface DimPlace {
  paperSpace?: boolean;
  owner?: string;
}

/**
 * 치수가 놓인 공간: 도면 공간 표지가 있거나 소유자가 배치 블록이면 'paper', 소유자가 모형 공간 블록이거나 소유자가 없으면 'model'
 * (DWG는 모형 공간 객체에 소유자 핸들을 적지 않고, R12 DXF의 객체 구역도 67이 없으면 모형 공간이다), 다른 블록 정의 안이면 null(모른다).
 * 새 치수는 놓기 전에 placeIn으로 자리를 정한다
 */
export function dimSpace(doc: CadDocument, d: DimPlace): 'model' | 'paper' | null {
  if (d.paperSpace) return 'paper';
  const o = d.owner;
  if (!o) return 'model';
  const ms = doc.blocks.get(MODEL_SPACE)?.recordHandle;
  if (ms && o === ms) return 'model';
  for (const l of doc.layouts) if (l.blockRecord === o && tableKey(l.blockName) !== MODEL_SPACE) return 'paper';
  return null;
}

/** 새 치수를 공간 space(블록 키)에 놓을 자리로: 소유 블록 레코드와 도면 공간 표지(dimSpace — 측정 문자의 DIMLFAC 규칙이 본다) */
export function placeIn(doc: CadDocument, space: string, d: DimPlace): void {
  const b = doc.blocks.get(space);
  if (b?.recordHandle) d.owner = b.recordHandle;
  d.paperSpace = /^\*PAPER_SPACE/i.test(space) ? true : undefined;
}

/**
 * 측정 문자에 쓰는 치수 변수: rawDimVars에서 모형 공간 치수의 음수 DIMLFAC만 1로 바꾼다.
 * 근거(AutoCAD 도움말, 우리말 요약): DIMLFAC — 양수는 모형 공간과 도면 공간 치수 모두에, 음수는 도면 공간에만 쓴다.
 * .NET 개발 안내서 "Dimension in Model Space and Paper Space" — 모형 공간에서 치수를 기입하면 DIMLFAC가 0보다 작아도 1.0을 쓴다.
 * 도면 공간과 공간을 모르는 치수(다른 블록 정의 안)는 이전처럼 그 크기를 쓴다(edit/dim/format.ts). 저장 값은 바꾸지 않는다
 */
export function measureVars(doc: CadDocument, d: Parameters<typeof rawDimVars>[1] & DimPlace): RawVars {
  const r = rawDimVars(doc, d);
  if (num(r.DIMLFAC, 1) < 0 && dimSpace(doc, d) === 'model') r.DIMLFAC = 1;
  return r;
}

/**
 * 측정값에 곱하는 DIMLFAC 크기(measureVars와 같은 규칙): 모형 공간 치수의 음수는 1, 그 밖에는 그 크기
 * (.NET 개발 안내서: DIMLFAC가 0보다 작으면 잰 거리에 그 절댓값을 곱한다)
 */
export function linearFactor(doc: CadDocument, lfac: number | string | undefined, d: DimPlace): number {
  const f = num(lfac, 1) || 1;
  return f < 0 && dimSpace(doc, d) === 'model' ? 1 : Math.abs(f);
}

const str = (v: number | string | undefined): string => (v === undefined || v === null ? '' : String(v));

/** 크기에 DIMSCALE을 곱한 치수 변수 */
export interface DimVars {
  raw: RawVars;
  scale: number;
  asz: number;
  tsz: number;
  exo: number;
  exe: number;
  dle: number;
  dli: number;
  gap: number;
  /** 문자 높이(스타일 고정 높이 우선) */
  txt: number;
  cen: number;
  fxl: number;
  fxlon: boolean;
  tvp: number;
  tfac: number;
  tad: number;
  just: number;
  tih: boolean;
  toh: boolean;
  tix: boolean;
  soxd: boolean;
  tofl: boolean;
  sah: boolean;
  se1: boolean;
  se2: boolean;
  sd1: boolean;
  sd2: boolean;
  atfit: number;
  tmove: number;
  upt: boolean;
  blk1: string;
  blk2: string;
  clrd: number;
  clre: number;
  clrt: number;
  ltype: string;
  ltex1: string;
  ltex2: string;
  lwd: number;
  lwe: number;
  txsty: string;
  textStyle: TextStyle | undefined;
  tfill: number;
  tfillclr: number;
  jogang: number;
  arcsym: number;
  txtdirection: number;
}

export function dimVars(doc: CadDocument, d: Pick<DimensionEntity, 'dimStyle' | 'overrides'> & { xdata?: DimensionEntity['xdata']; dimType?: number; subtype?: string } & DimPlace): DimVars {
  // 치수 그림의 문자: 모형 공간 치수의 음수 DIMLFAC는 1(measureVars)
  const r = measureVars(doc, d);
  let scale = num(r.DIMSCALE, 1);
  if (!(scale > 0)) scale = 1;
  const S = (k: string, def: number) => num(r[k], def) * scale;
  const B = (k: string) => num(r[k], 0) !== 0;
  const txsty = str(r.DIMTXSTY) || 'Standard';
  const textStyle = doc.textStyles.get(tableKey(txsty)) ?? doc.textStyles.get('STANDARD');
  let txt = S('DIMTXT', 0.18);
  if (textStyle && textStyle.height > 0) txt = textStyle.height;
  const blk = str(r.DIMBLK);
  const sah = B('DIMSAH');
  return {
    raw: r,
    scale,
    asz: S('DIMASZ', 0.18),
    tsz: S('DIMTSZ', 0),
    exo: S('DIMEXO', 0.0625),
    exe: S('DIMEXE', 0.18),
    dle: S('DIMDLE', 0),
    dli: S('DIMDLI', 0.38),
    gap: S('DIMGAP', 0.09),
    txt,
    cen: S('DIMCEN', 0.09),
    fxl: S('DIMFXL', 1),
    fxlon: B('DIMFXLON'),
    tvp: num(r.DIMTVP, 0),
    tfac: num(r.DIMTFAC, 1) || 1,
    tad: num(r.DIMTAD, 0),
    just: num(r.DIMJUST, 0),
    tih: B('DIMTIH'),
    toh: B('DIMTOH'),
    tix: B('DIMTIX'),
    soxd: B('DIMSOXD'),
    tofl: B('DIMTOFL'),
    sah,
    se1: B('DIMSE1'),
    se2: B('DIMSE2'),
    sd1: B('DIMSD1'),
    sd2: B('DIMSD2'),
    atfit: num(r.DIMATFIT, 3),
    tmove: num(r.DIMTMOVE, 0),
    upt: B('DIMUPT'),
    blk1: sah ? str(r.DIMBLK1) : blk,
    blk2: sah ? str(r.DIMBLK2) : blk,
    clrd: num(r.DIMCLRD, 0),
    clre: num(r.DIMCLRE, 0),
    clrt: num(r.DIMCLRT, 0),
    ltype: str(r.DIMLTYPE),
    ltex1: str(r.DIMLTEX1),
    ltex2: str(r.DIMLTEX2),
    lwd: num(r.DIMLWD, -2),
    lwe: num(r.DIMLWE, -2),
    txsty: textStyle?.name ?? txsty,
    textStyle,
    tfill: num(r.DIMTFILL, 0),
    tfillclr: num(r.DIMTFILLCLR, 0),
    jogang: num(r.DIMJOGANG, Math.PI / 4),
    arcsym: num(r.DIMARCSYM, 0),
    txtdirection: num(r.DIMTXTDIRECTION, 0),
  };
}
