/** 편집 결과 형식 */
import type { BlockDef, CadDocument, Entity, Vec2 } from '../../core/model';
import { pushAll } from '../../core/arrays';

export interface EditResult {
  /** 새 객체(핸들 '' — 호출한 쪽이 붙인다) */
  add?: Entity[];
  /** 핸들을 유지한 채 바뀐 객체 */
  replace?: Entity[];
  /** 지울 핸들 */
  remove?: string[];
  /** 새로 만들었거나 바꾼 블록 정의(예: 익명 치수 블록) */
  blocks?: BlockDef[];
  /** 결과가 없거나 근사했을 때의 AutoCAD식 안내 */
  message?: string;
}

export type GripKind = 'end' | 'mid' | 'cen' | 'qua' | 'ins' | 'vertex' | 'ctrl' | 'fit' | 'text';

export interface GripPoint {
  id: string;
  point: Vec2;
  kind: GripKind;
}

export interface TransformOptions {
  /** MIRRTEXT = 1: 문자도 거울상으로(기본 거짓 = 읽을 수 있게) */
  mirrorText?: boolean;
  /** MIRRHATCH = 1: 해치 무늬도 대칭(기본 거짓 = 무늬 방향 유지) */
  mirrorHatch?: boolean;
  /** Z 이동 */
  dz?: number;
  /** 내부용: MTEXT까지 정확한 거울상(분해) */
  exact?: boolean;
  /**
   * 내부용(commitResults로 가는 변환): 치수 블록 내용 옮기기를 미룬다. commitResults가 치수 생성기로 블록을 다시 만들므로
   * 다시 만들지 못한 치수의 블록만 fillDeferredBlock으로 채운다
   */
  deferDimBlocks?: boolean;
  /**
   * 내부용(글자를 읽을 수 있게 두는 대칭): 여러 단 MTEXT 묶음을 통째로 옮길 때 단 핸들 → 묶음 전체 상자(그 단 삽입점 기준 글자 좌표).
   * 있으면 제 상자 대신 이 상자를 거울상 자리에 둬 단 차례가 뒤집히지 않는다(R2018 꼴 객체 하나와 같은 결과)
   */
  columnBoxes?: ReadonlyMap<string, { minX: number; minY: number; maxX: number; maxY: number }>;
}

